import styles from "./schedule-row.module.less";
import Link from "@/core/components/primitives/link/link";
import {
  RestaurantContent,
  RideContent,
  RideContentSchedule,
} from "@/core/components/primitives/calendar-groupings/calendar-groupings";
import { GatsbyImage } from "gatsby-plugin-image";
import { DateHelper, PlaceholderImageHelper } from "@/core/helpers";
import { buttonLinkIsInternal } from "@/core/components/primitives/parks-button/parks-button";
import { Translation } from "@/core/labels/i18n";
import { useTranslation } from "react-i18next";
import { ContentfulEvent } from "@parksandresorts/webapiproxy-types";
import { getRideStoppageInfo } from "@/core/helpers/get-ride-stoppage-info";
import Icon, { IconName } from "@/core/components/primitives/icon/icon";
import { orderBy } from "lodash-es";

const getTimeStringForEvent = (event: ContentfulEvent, t: Translation) => {
  const { startDateAndTime, endDateAndTime, cancelled, cancelledText } = event;

  const isDateToday = DateHelper.isToday(startDateAndTime);
  const startTime = DateHelper.toStringTimeHHMM(startDateAndTime);
  const endTime = endDateAndTime && DateHelper.toStringTimeHHMM(endDateAndTime);

  if (cancelled) {
    return cancelledText ?? t("scheduleRowCancelled");
  }

  if (isDateToday) {
    const isRideAlreadyOpen = DateHelper.hasTimePassedToday(startTime);
    const isRideClosed = endTime ? DateHelper.hasTimePassedToday(endTime) : null;

    if (isRideClosed) {
      return t("scheduleRowClosedToday");
    }

    if (isRideAlreadyOpen) {
      return t("scheduleRowOpen") + (endTime ? " - " + endTime : "");
    }
  }

  return startTime + (endTime ? " - " + endTime : "");
};

const getRideDisplayInfo = (content: RideContentSchedule, t: Translation): { iconName: IconName; text: string } => {
  const publicTimes = content.scheduleForDate.operatingTimes?.filter((ot) => ot.isOpenToPublic) ?? [];

  const mappedPasses = orderBy(publicTimes, "opensOn").map((publicTime) => {
    const opensTime = DateHelper.toStringTimeHHMM(publicTime.opensOn);
    const closesTime = DateHelper.toStringTimeHHMM(publicTime.closesOn);

    if (DateHelper.isToday(publicTime.opensOn)) {
      if (DateHelper.hasTimePassedToday(closesTime)) return null;
      if (DateHelper.hasTimePassedToday(opensTime)) {
        if (content.queueState !== "open") {
          const { stoppageIcon, stoppageTextCurrentLocale } = getRideStoppageInfo(
            content.queueState,
            content.stoppage,
            t,
          );
          return { iconName: stoppageIcon ?? "hourglassTop", text: stoppageTextCurrentLocale } as const;
        }
        return t("scheduleRowOpen") + " - " + closesTime;
      }
    }

    return opensTime + " - " + closesTime;
  });
  const closedPass = mappedPasses.find(
    (p): p is Extract<typeof p, { iconName: string }> => !!p && typeof p !== "string",
  );
  if (closedPass) {
    return closedPass;
  }

  const openingHoursPasses = mappedPasses.filter((p): p is string => typeof p === "string");
  if (openingHoursPasses.length === 0) {
    return { iconName: "hotel", text: t("scheduleRowClosedToday") };
  }

  return { iconName: "clock", text: openingHoursPasses.join(", ") };
};

const RowContent = (content: RestaurantContent | RideContent) => {
  const { t } = useTranslation();
  const gatsbyImageData = content.imageInList?.gatsbyImageData;
  const fileUrl = content.imageInList?.file?.url;
  const fallbackImageKey = content.type === "restaurant" ? "restaurantImage" : "rideImage";
  const fallbackImage = PlaceholderImageHelper.getPlaceholderImage(fallbackImageKey);
  const { iconName, text } =
    content.type === "ride" && content.contentSource === "schedule"
      ? getRideDisplayInfo(content, t)
      : { iconName: "clock" as IconName, text: content.event ? getTimeStringForEvent(content.event, t) : "" };

  return (
    <>
      {gatsbyImageData ? (
        <GatsbyImage className={styles.image} image={gatsbyImageData} alt={content.title} />
      ) : fileUrl ? (
        <img className={styles.image} src={fileUrl} alt={content.title} />
      ) : (
        <img className={styles.image} src={fallbackImage} alt={content.title} />
      )}
      <div className={styles.textWrapper}>
        <h5 className={styles.title}>{content.title}</h5>
        <p className={[styles.bodyText, "p_small"].join(" ")}>
          <Icon name={iconName} size="l" className={styles.icon} />
          {text}
        </p>
      </div>
    </>
  );
};

const ScheduleRow = (content: RestaurantContent | RideContent) => {
  const url = content.type === "restaurant" ? content.restaurantPageLink?.slug : content.ridePageLink?.slug;

  if (url) {
    return (
      <Link
        internalLink={buttonLinkIsInternal(url) ? url : undefined}
        externalLink={buttonLinkIsInternal(url) ? undefined : url}
        className={styles.row}
        title={content.title}
      >
        <RowContent {...content} />
        <div className={styles.rightIconWrapper}>
          <Icon name="chevron-right" className={`${styles.rightIcon} ${styles.icon}`} />
        </div>
      </Link>
    );
  }

  return (
    <div className={[styles.row, styles.noLink].join(" ")}>
      <RowContent {...content} />
    </div>
  );
};

export default ScheduleRow;
